<template>
  <div class="office-page">
    <AppSidebar />
    <main class="main">
      <header class="page-head">
        <div><h2>公文审批</h2><p>业务申请、逐级审批、公文流转与模板复用</p></div>
        <el-button type="primary" size="small" @click="openDoc()">新建公文</el-button>
      </header>

      <section class="summary">
        <div class="summary-metrics"><div class="metric"><small>我发起的</small><b>{{ docs.length }}</b></div><div class="metric warn"><small>待我处理</small><b>{{ pending.length }}</b></div><div class="metric success"><small>已通过</small><b>{{ approved.length }}</b></div></div>
        <div class="template-launch"><div class="launch-label"><b>快捷发起</b></div><div class="launch-buttons"><button v-for="item in quickTypes" :key="item.key" @click="fromType(item.key)"><i :class="item.icon"></i>{{ item.label }}</button></div></div>
      </section>

      <el-tabs v-model="tab" class="office-tabs">
        <el-tab-pane label="公文工作台" name="workbench">
          <section class="document-board">
            <article class="document-column submitted-column">
              <header class="column-head"><div><b>我提交的公文</b><span>起草、提交、发布与接收确认</span></div><el-button type="text" size="mini" @click="openDoc()">+ 新建</el-button></header>
              <div v-if="docs.length" class="document-card-list"><article v-for="row in docsShown" :key="row.id" class="document-item-card"><div class="card-topline"><el-tag size="mini" effect="plain">{{ typeLabel(row.document_type) }}</el-tag><el-tag size="mini" :type="tag(row.status)">{{ state(row.status) }}</el-tag></div><button class="card-title" @click="detail(row)">{{ row.title }}</button><p class="card-preview">{{ documentPreview(row.content) }}</p><div class="card-people-line"><span class="card-label">审批人</span><div v-if="row.reviewer_name" class="sender-person"><img :src="avatar(row.reviewer_name)" /><b>{{ row.reviewer_name }}</b></div><span v-else class="reviewer-empty">{{ row.status === 'draft' ? '尚未提交' : '审批中' }}</span><i></i><span class="card-label">接收人</span><div v-if="recipientAvatarNames((row.recipient_summary || {}).names).length" class="recipient-avatars" @click="detail(row)"><img v-for="name in recipientAvatarNames((row.recipient_summary || {}).names)" :key="name" :src="avatar(name)" /><em v-if="((row.recipient_summary || {}).names || []).length > 3">+{{ ((row.recipient_summary || {}).names || []).length - 3 }}</em></div><span v-else class="recipient-text">未指定</span><small v-if="recipientAvatarNames((row.recipient_summary || {}).names).length" class="recipient-inline-names">{{ recipientLabel(row.recipient_summary) }}</small><small v-if="row.status === 'published'" class="receipt-state">已确认 {{ (row.recipient_summary || {}).confirmed || 0 }}/{{ (row.recipient_summary || {}).total || 0 }}</small></div><footer class="card-footer"><time>{{ dateTime(row.updated_at) }}</time><div><el-button size="mini" type="text" @click="detail(row)">查看</el-button><el-button v-if="row.status==='draft'" size="mini" type="primary" @click="submit(row)">提交审批</el-button><el-button v-if="row.status==='approved'" size="mini" type="success" @click="publish(row)">发布</el-button></div></footer></article><button v-if="docs.length > 2" class="show-more" @click="showAllDocs=!showAllDocs">{{ showAllDocs ? '收起' : `查看全部（${docs.length}）` }}</button></div>
              <el-empty v-else :image-size="70" description="暂无我提交的公文" />
            </article>
            <article class="document-column pending-column">
              <header class="column-head"><div><b>待我审批</b><span>请及时处理需要流转的事项</span></div><el-tag size="mini" type="warning">{{ pending.length }} 项待处理</el-tag></header>
              <div v-if="pending.length" class="document-card-list"><article v-for="row in pendingShown" :key="row.id" class="document-item-card approval-item-card"><div class="card-topline"><el-tag size="mini" type="warning" effect="plain">待我审批</el-tag><time>{{ dateTime(row.created_at) }}</time></div><button class="card-title" @click="approvalDetail(row)">{{ row.title }}</button><div class="card-people-line"><span class="card-label">提交人</span><div class="sender-person"><img :src="avatar(row.submitter_name)" /><b>{{ row.submitter_name || '提交人' }}</b></div><i></i><span class="card-label">接收人</span><div v-if="recipientAvatarNames(row.recipient_names).length" class="recipient-avatars" @click="approvalDetail(row)"><img v-for="name in recipientAvatarNames(row.recipient_names)" :key="name" :src="avatar(name)" /><em v-if="(row.recipient_names || []).length > 3">+{{ (row.recipient_names || []).length - 3 }}</em></div><span v-else class="recipient-text">未指定</span><small v-if="recipientAvatarNames(row.recipient_names).length" class="recipient-inline-names">{{ recipientNames(row.recipient_names) }}</small></div><footer class="card-footer"><el-button size="mini" type="text" @click="approvalDetail(row)">查看详情</el-button><div><el-button type="success" size="mini" @click="approve(row)">通过</el-button><el-button type="danger" size="mini" @click="reject(row)">驳回</el-button></div></footer></article><button v-if="pending.length > 2" class="show-more" @click="showAllPending=!showAllPending">{{ showAllPending ? '收起' : `查看全部（${pending.length}）` }}</button></div>
              <el-empty v-else :image-size="70" description="当前没有待处理审批" />
            </article>
          </section>
          <section class="approval-tip"><i class="el-icon-info"></i><span>点击公文标题可查看正文、接收人和审批信息；审批结果会同步通知提交人。</span></section>
        </el-tab-pane>

        <el-tab-pane label="模板库" name="templates">
          <section class="template-toolbar"><div><b>公文模板库</b><p>内置模板可直接使用和预览；自建模板支持编辑、复制与删除。</p></div><el-button type="primary" size="small" @click="openTemplate()">新建模板</el-button></section>
          <div class="template-grid">
            <article v-for="item in templates" :key="item.id" class="template-card">
              <div class="template-card-head"><span class="template-icon" :class="templateTheme(item)"><i :class="templateIcon(item)"></i></span><el-tag size="mini" :type="item.is_system ? 'info' : 'success'">{{ item.is_system ? '内置模板' : '自建模板' }}</el-tag></div>
              <b>{{ item.name }}</b><p>{{ templatePreview(item.content) }}</p>
              <footer class="template-actions" :class="{ custom: !item.is_system }"><button class="template-use" @click="useTemplate(item)"><i class="el-icon-edit-outline"></i>使用模板</button><button @click="previewTemplate(item)"><i class="el-icon-view"></i>预览</button><button v-if="!item.is_system" @click="openTemplate(item)"><i class="el-icon-edit"></i>编辑</button><button v-if="!item.is_system" class="danger" @click="removeTemplate(item)"><i class="el-icon-delete"></i>删除</button></footer>
            </article>
            <el-empty v-if="!templates.length" description="暂无模板" :image-size="70" />
          </div>
        </el-tab-pane>
      </el-tabs>
    </main>

    <el-dialog :title="form.id ? '编辑公文' : '新建公文'" :visible.sync="docVisible" width="720px" @closed="resetRecipientPicker">
      <el-form :model="form" label-width="76px" size="small" class="document-dialog-form"><section class="document-form-card"><div class="document-form-card-title"><i class="el-icon-edit-outline"></i>基本信息</div><el-form-item label="公文标题"><el-input v-model="form.title" placeholder="请输入公文标题" /></el-form-item><el-form-item label="公文类型"><el-select v-model="form.document_type" style="width:100%"><el-option v-for="item in documentTypes" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item></section><section class="document-form-card"><div class="document-form-card-title"><i class="el-icon-user-solid"></i>接收成员</div><div v-for="department in recipientTree" :key="department.id" class="recipient-department"><div class="recipient-department-card"><el-checkbox :value="isRecipientGroupChecked(department)" :indeterminate="isRecipientGroupPartial(department)" @change="toggleRecipientGroup(department, $event)">{{ department.label }}</el-checkbox><small>勾选部门将选择该部门全部成员</small></div><el-collapse v-model="recipientExpanded" class="recipient-groups"><el-collapse-item v-for="group in department.children" :key="group.id" :name="group.id"><template slot="title"><el-checkbox :value="isRecipientGroupChecked(group)" :indeterminate="isRecipientGroupPartial(group)" @click.native.stop @change="toggleRecipientGroup(group, $event)">{{ group.label }}</el-checkbox><span class="recipient-group-count">{{ group.children.length }} 人</span></template><div class="recipient-member-list"><el-checkbox v-for="member in group.children" :key="member.id" v-model="form.recipientIds" :label="member.user_id">{{ member.label }}</el-checkbox></div></el-collapse-item></el-collapse></div></section><section class="document-form-card"><div class="document-form-card-title"><i class="el-icon-document"></i>正文内容</div><el-form-item label="正文"><el-input v-model="form.content" type="textarea" :rows="9" placeholder="请输入公文正文内容" /></el-form-item></section></el-form>
      <span slot="footer"><el-button @click="docVisible=false">取消</el-button><el-button type="primary" @click="saveDoc">保存草稿</el-button></span>
    </el-dialog>
    <el-dialog :title="templateForm.id ? '编辑模板' : '新建模板'" :visible.sync="templateVisible" width="680px">
      <el-form :model="templateForm" label-width="76px" size="small" class="document-dialog-form"><section class="document-form-card"><div class="document-form-card-title"><i class="el-icon-notebook-2"></i>模板信息</div><el-form-item label="模板名称"><el-input v-model="templateForm.name" placeholder="例如：项目进度周报" /></el-form-item><el-form-item label="适用类型"><el-select v-model="templateForm.document_type" style="width:100%"><el-option v-for="item in documentTypes" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item></section><section class="document-form-card"><div class="document-form-card-title"><i class="el-icon-document-copy"></i>模板正文</div><el-form-item label="正文内容"><el-input v-model="templateForm.content" type="textarea" :rows="11" placeholder="可使用双花括号变量作为后续填写提示" /></el-form-item></section></el-form>
      <span slot="footer"><el-button @click="templateVisible=false">取消</el-button><el-button type="primary" @click="saveTemplate">保存模板</el-button></span>
    </el-dialog>
    <el-dialog :title="previewTitle" :visible.sync="previewVisible" width="620px"><pre>{{ previewContent }}</pre></el-dialog>
    <el-dialog title="公文详情" :visible.sync="detailVisible" width="650px"><div class="detail-title">{{ current && current.title }}</div><pre>{{ content }}</pre><section v-if="current && current.recipients && current.recipients.length" class="receipt-panel"><div class="receipt-head"><b>接收确认（{{ (current.recipient_summary || {}).confirmed || 0 }}/{{ (current.recipient_summary || {}).total || 0 }}）</b><span>发布后跟踪知悉情况</span></div><div class="receipt-list"><span v-for="item in current.recipients" :key="item.user_id"><img :src="avatar(item.display_name)" /><b>{{ item.display_name }}</b><small :class="{ confirmed: receiptConfirmed(item.user_id) }">{{ receiptConfirmed(item.user_id) ? '已确认' : '待确认' }}</small></span></div><el-button v-if="canConfirmCurrent" type="primary" size="mini" @click="confirmReceipt">确认已知悉</el-button></section></el-dialog>
  </div>
</template>

<script>
import AppSidebar from '../components/Sidebar/index.vue'
const quickTypes = [
  { key: 'notice', type: 'notice', templateName: '会议通知', label: '会议通知', icon: 'el-icon-message' },
  { key: 'leave', type: 'request', templateName: '请假申请', label: '请假申请', icon: 'el-icon-date' },
  { key: 'reimbursement', type: 'request', templateName: '报销申请', label: '报销申请', icon: 'el-icon-wallet' },
  { key: 'procurement', type: 'request', templateName: '采购申请', label: '采购申请', icon: 'el-icon-goods' },
]
const documentTypes = [{ value: 'notice', label: '通知' }, { value: 'request', label: '申请' }, { value: 'report', label: '报告' }, { value: 'minutes', label: '会议纪要' }]
export default {
  components: { AppSidebar },
  data: () => ({ tab: 'workbench', quickTypes, documentTypes, docVisible: false, templateVisible: false, detailVisible: false, previewVisible: false, previewTitle: '', previewContent: '', current: null, showAllDocs: false, showAllPending: false, recipientExpanded: [], form: { document_type: 'notice', recipientIds: [] }, templateForm: { document_type: 'notice' } }),
  computed: {
    ws() { return this.$store.getters['workspace/activeWorkspace'] || {} },
    members() { return (this.$store.state.office.organization || { members: [] }).members },
    recipientTree() {
      const organization = this.$store.state.office.organization || { groups: [], members: [], department: null }
      const memberNode = member => ({ id: `recipient:${member.user_id}`, user_id: member.user_id, label: member.display_name })
      const direct = (organization.members || []).filter(member => !member.group_id)
      const children = []
      if (direct.length) children.push({ id: 'recipient-direct', label: '部门直属成员', children: direct.map(memberNode) })
      ;(organization.groups || []).forEach(group => {
        const groupMembers = (organization.members || []).filter(member => member.group_id === group.id)
        if (groupMembers.length) children.push({ id: `recipient-group:${group.id}`, label: group.name, children: groupMembers.map(memberNode) })
      })
      return children.length ? [{ id: 'recipient-department', label: (organization.department || {}).name || '智慧办公演示部', children }] : []
    },
    currentUser() { return this.$store.getters['user/currentUser'] || {} },
    docs() { return this.$store.state.office.documents || [] },
    approvals() { return this.$store.state.office.approvals || [] },
    templates() { return this.$store.state.office.templates || [] },
    pending() { return this.approvals.filter(x => x.can_handle) },
    docsShown() { return this.showAllDocs ? this.docs : this.docs.slice(0, 2) },
    pendingShown() { return this.showAllPending ? this.pending : this.pending.slice(0, 2) },
    approved() { return this.docs.filter(x => ['approved', 'published'].includes(x.status)) },
    content() { return this.current ? this.current.content : '' },
    canConfirmCurrent() { return this.current && this.current.status === 'published' && (this.current.recipients || []).some(item => item.user_id === this.currentUser.id) && !this.receiptConfirmed(this.currentUser.id) },
  },
  watch: { 'ws.id': { immediate: true, handler() { this.load() } } },
  methods: {
    load() { if (this.ws.id && this.ws.domain === 'office') return Promise.all(['loadDocuments', 'loadApprovals', 'loadTemplates', 'loadOrganization'].map(a => this.$store.dispatch('office/' + a, this.ws.id))) },
    openDoc() { this.form = { document_type: 'notice', recipientIds: [] }; this.recipientExpanded = []; this.docVisible = true },
    fromType(key) { const item = quickTypes.find(x => x.key === key); const x = this.templates.find(a => a.is_system && a.name === item.templateName) || this.templates.find(a => a.is_system && a.document_type === item.type); this.form = { title: x ? x.name : item.templateName, content: x ? x.content : '', document_type: item.type, recipientIds: [] }; this.recipientExpanded = []; this.docVisible = true },
    useTemplate(item) { this.form = { title: item.name, content: item.content, document_type: item.document_type, recipientIds: [] }; this.recipientExpanded = []; this.tab = 'workbench'; this.docVisible = true },
    resetRecipientPicker() { this.recipientExpanded = [] },
    recipientIds(node) { return (node.children || []).reduce((ids, child) => ids.concat(child.children ? this.recipientIds(child) : [child.user_id]), []) },
    isRecipientGroupChecked(node) { const ids = this.recipientIds(node); return ids.length > 0 && ids.every(id => this.form.recipientIds.includes(id)) },
    isRecipientGroupPartial(node) { const ids = this.recipientIds(node); const selected = ids.filter(id => this.form.recipientIds.includes(id)).length; return selected > 0 && selected < ids.length },
    toggleRecipientGroup(node, checked) { const ids = this.recipientIds(node); const selected = new Set(this.form.recipientIds); ids.forEach(id => checked ? selected.add(id) : selected.delete(id)); this.form.recipientIds = [...selected] },
    async saveDoc() { if (!this.form.title || !this.form.content) return this.$message.warning('请填写标题和正文'); const recipients = this.members.filter(item => this.form.recipientIds.includes(item.user_id)).map(item => ({ user_id: item.user_id, display_name: item.display_name })); await this.$store.dispatch('office/createDocument', { title: this.form.title, content: this.form.content, document_type: this.form.document_type, recipients, workspace_id: this.ws.id }); this.docVisible = false; this.$message.success('公文草稿已保存'); this.load() },
    async submit(row) { await this.$store.dispatch('office/submitDocument', { id: row.id, data: {}, workspaceId: this.ws.id }); this.$message.success('已提交审批') },
    async publish(row) { await this.$store.dispatch('office/publishDocument', { id: row.id, workspaceId: this.ws.id }); this.$message.success('公文已发布') },
    async detail(row) { this.current = await this.$store.dispatch('office/getDocument', row.id); this.detailVisible = true },
    async approvalDetail(row) { const result = await this.$store.dispatch('office/getApproval', row.id); this.current = result.document; this.detailVisible = true },
    receiptConfirmed(userId) { return (this.current && this.current.receipts || []).some(item => item.recipient_id === userId && item.confirmed_at) },
    async confirmReceipt() { await this.$store.dispatch('office/confirmDocumentReceipt', { id: this.current.id, workspaceId: this.ws.id }); this.current = await this.$store.dispatch('office/getDocument', this.current.id); this.$message.success('已确认知悉该公文') },
    async approve(row) { await this.$store.dispatch('office/approve', { id: row.id, data: {}, workspaceId: this.ws.id }); this.$message.success('审批已通过') },
    async reject(row) { try { const result = await this.$prompt('请填写驳回意见', '驳回审批', { inputPattern: /\S+/, inputErrorMessage: '驳回意见不能为空' }); await this.$store.dispatch('office/reject', { id: row.id, data: { comment: result.value }, workspaceId: this.ws.id }); this.$message.success('已驳回并通知提交人') } catch (e) {} },
    openTemplate(item) { this.templateForm = item ? { ...item } : { document_type: 'notice' }; this.templateVisible = true },
    async saveTemplate() { if (!this.templateForm.name || !this.templateForm.content) return this.$message.warning('请填写模板名称和正文'); if (this.templateForm.id) await this.$store.dispatch('office/updateTemplate', { id: this.templateForm.id, data: this.templateForm, workspaceId: this.ws.id }); else await this.$store.dispatch('office/createTemplate', { ...this.templateForm, workspace_id: this.ws.id }); this.templateVisible = false; this.$message.success('模板已保存') },
    async removeTemplate(item) { try { await this.$confirm(`确认删除模板“${item.name}”吗？`, '删除模板', { type: 'warning' }); await this.$store.dispatch('office/deleteTemplate', { id: item.id, workspaceId: this.ws.id }); this.$message.success('模板已删除') } catch (e) {} },
    previewTemplate(item) { this.previewTitle = item.name; this.previewContent = item.content || '暂无模板内容'; this.previewVisible = true },
    state(s) { return ({ draft: '草稿', reviewing: '审批中', approved: '已批准', published: '已发布', rejected: '已驳回' })[s] || s },
    tag(s) { return ({ draft: 'info', reviewing: 'warning', approved: 'success', published: 'success', rejected: 'danger' })[s] || '' },
    typeLabel(t) { return (documentTypes.find(x => x.value === t) || {}).label || '公文' },
    templateIcon(item) { const byName = { '会议通知': 'el-icon-message', '会议纪要': 'el-icon-notebook-2', '工作推进通知': 'el-icon-document-checked', '阶段验收通知': 'el-icon-finished', '跨组协同通知': 'el-icon-connection', '工作周报': 'el-icon-data-analysis', '请假申请': 'el-icon-date', '报销申请': 'el-icon-wallet', '采购申请': 'el-icon-goods' }; return byName[item.name] || ({ notice: 'el-icon-message', request: 'el-icon-document', report: 'el-icon-tickets', minutes: 'el-icon-notebook-2' })[item.document_type] || 'el-icon-document' },
    templateTheme(item) { return ({ notice: 'blue', request: 'orange', report: 'purple', minutes: 'green' })[item.document_type] || (item.is_system ? 'blue' : 'teal') },
    templatePreview(value) { return String(value || '暂无模板说明').replace(/\s+/g, ' ').slice(0, 55) },
    documentPreview(value) { return String(value || '暂无正文内容').replace(/\s+/g, ' ').slice(0, 70) },
    dateTime(value) { return String(value || '—').replace('T', ' ').slice(0, 16) },
    recipientAvatarNames(names) { return Array.isArray(names) ? names.filter(Boolean).slice(0, 3) : [] },
    recipientNames(names) { return Array.isArray(names) && names.length ? names.slice(0, 3).join('、') + (names.length > 3 ? ' 等' : '') : '未指定' },
    recipientLabel(summary) { return this.recipientNames((summary || {}).names) || '未指定' },
    avatar(name) { const key = String(name || '').charAt(0); const map = { '王': 'wang-manager', '李': 'li-lead', '周': 'zhou-lead', '张': 'zhang-lead', '陈': 'chen-member', '刘': 'liu-member', '赵': 'zhao-member', '杨': 'yang-member', '吴': 'wu-member', '孙': 'sun-member', '钱': 'qian-member', '冯': 'feng-member' }; try { return require(`../assets/office-avatars/${map[key] || 'wang-manager'}.png`) } catch (e) { return '' } },
  },
}
